import React, { useRef, useCallback } from 'react';
import { UploadIcon } from './icons/UploadIcon';

interface FileUploadProps {
  onFileChange: (files: File[] | null) => void;
  disabled?: boolean;
}

export const FileUpload: React.FC<FileUploadProps> = ({ onFileChange, disabled }) => {
  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleFileSelection = useCallback((selectedFileList: FileList | null) => {
    if (selectedFileList && selectedFileList.length > 0) {
      const allowedExtensions = ['.docx', '.doc', '.pdf', '.txt', '.md'];
      const allowedTypes = [
        'audio/',
        'text/',
        'application/pdf',
        'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
        'application/msword'
      ];

      const allowedFiles = Array.from(selectedFileList).filter(file => {
        const typeMatch = allowedTypes.some(type => file.type.startsWith(type));
        const extensionMatch = allowedExtensions.some(ext => file.name.toLowerCase().endsWith(ext));
        return typeMatch || extensionMatch;
      });

      if (allowedFiles.length > 0) {
        onFileChange(allowedFiles);
      } else {
        onFileChange(null);
        alert("Please select valid files: Audio, Text, Word documents, or PDFs.");
        if (fileInputRef.current) fileInputRef.current.value = "";
      }
    }
  }, [onFileChange]);

  const handleInputChange = (event: React.ChangeEvent<HTMLInputElement>) => {
    handleFileSelection(event.target.files);
  };

  const openFileDialog = () => {
    if (!disabled && fileInputRef.current) {
        fileInputRef.current.click();
    }
  };

  return (
    <>
      <input 
        ref={fileInputRef} 
        id="file-upload" 
        type="file" 
        accept="audio/*,text/plain,text/markdown,.txt,.md,.docx,.doc,application/pdf" 
        multiple 
        onChange={handleInputChange} 
        className="hidden" 
        disabled={disabled} 
      />
      <button
        onClick={openFileDialog}
        disabled={disabled}
        className="w-20 h-20 button-etched rounded-full flex items-center justify-center disabled:opacity-50 disabled:cursor-not-allowed"
        aria-label="Upload files"
      >
        <UploadIcon className="w-8 h-8"/>
      </button>
    </>
  );
};

import React, { useState, useCallback, useRef, useReducer, DragEvent, useEffect } from 'react';
import ReactDOM from 'react-dom/client';
import { FileUpload } from './components/FileUpload';
import { NoteDisplay } from './components/NoteDisplay';
import { ProcessingAnimation } from './components/ProcessingAnimation';
import { ErrorMessage } from './components/ErrorMessage';
import { generateNotesFromFiles, generateSpecificInfoFromFiles } from './services/geminiService';
import { SparklesIcon } from './components/icons/SparklesIcon';
import { ArrowPathIcon } from './components/icons/ArrowPathIcon';
import { CallRecorder } from './components/CallRecorder';
import { ChatQuery } from './components/ChatQuery';
import { UploadIcon } from './components/icons/UploadIcon';

type Status = 'idle' | 'processing' | 'success' | 'error';
type Query = {
  text: string;
  answer: string;
  isLoading: boolean;
  error: string | null;
};

interface State {
  status: Status;
  uploadedFiles: File[];
  recordedAudioBlob: Blob | null;
  processedInitialAudios: File[] | null;
  generatedNotes: string | null;
  editedNotes: string | null;
  error: string | null;
  isRecording: boolean;
  queries: Query[];
  processingMessage: string;
}

type Action =
  | { type: 'START_PROCESSING'; message: string }
  | { type: 'PROCESSING_SUCCESS'; notes: string; processedAudios: File[] }
  | { type: 'PROCESSING_ERROR'; error: string }
  | { type: 'SET_UPLOADED_FILES'; files: File[] }
  | { type: 'START_RECORDING' }
  | { type: 'STOP_RECORDING'; blob: Blob }
  | { type: 'RESET' }
  | { type: 'CLEAR_ERROR' }
  | { type: 'START_QUERY'; queryText: string }
  | { type: 'QUERY_SUCCESS'; queryText: string; answer: string }
  | { type: 'QUERY_ERROR'; queryText: string; error: string }
  | { type: 'UPDATE_EDITED_NOTES'; notes: string };


const initialState: State = {
  status: 'idle',
  uploadedFiles: [],
  recordedAudioBlob: null,
  processedInitialAudios: null,
  generatedNotes: null,
  editedNotes: null,
  error: null,
  isRecording: false,
  queries: [],
  processingMessage: 'Analyzing files...',
};

function appReducer(state: State, action: Action): State {
  switch (action.type) {
    case 'START_PROCESSING':
      return { ...initialState, status: 'processing', processingMessage: action.message };
    case 'PROCESSING_SUCCESS':
      return { ...state, status: 'success', generatedNotes: action.notes, editedNotes: action.notes, processedInitialAudios: action.processedAudios, error: null };
    case 'PROCESSING_ERROR':
      return { ...state, status: 'error', error: action.error };
    case 'SET_UPLOADED_FILES':
      return { ...state, uploadedFiles: action.files, recordedAudioBlob: null };
    case 'START_RECORDING':
      return { ...initialState, isRecording: true };
    case 'STOP_RECORDING':
      return { ...state, isRecording: false, recordedAudioBlob: action.blob };
    case 'RESET':
      return initialState;
    case 'CLEAR_ERROR':
       return { ...state, error: null, status: state.generatedNotes ? 'success' : 'idle' };
    case 'START_QUERY':
      return { ...state, queries: [...state.queries, { text: action.queryText, answer: '', isLoading: true, error: null }] };
    case 'QUERY_SUCCESS':
      return {
        ...state,
        queries: state.queries.map(q => q.text === action.queryText ? { ...q, answer: action.answer, isLoading: false } : q)
      };
    case 'QUERY_ERROR':
      return {
        ...state,
        queries: state.queries.map(q => q.text === action.queryText ? { ...q, error: action.error, isLoading: false } : q)
      };
    case 'UPDATE_EDITED_NOTES':
      return { ...state, editedNotes: action.notes };
    default:
      return state;
  }
}

// --- Toast Component ---
const Toast: React.FC<{ message: string; onClose: () => void }> = ({ message, onClose }) => {
    useEffect(() => {
        const timer = setTimeout(onClose, 3000);
        return () => clearTimeout(timer);
    }, [onClose]);

    return (
        <div className="fixed bottom-8 left-1/2 transform -translate-x-1/2 z-50 animate-fade-in-stagger">
            <div className="bg-gray-900/90 text-white px-6 py-3 rounded-full shadow-2xl backdrop-blur-md flex items-center border border-white/10">
                <SparklesIcon className="w-4 h-4 text-accent-primary mr-3" />
                <span className="text-sm font-medium">{message}</span>
            </div>
        </div>
    );
};


const App: React.FC = () => {
  const [state, dispatch] = useReducer(appReducer, initialState);
  const [isDragging, setIsDragging] = useState(false);
  const [toastMessage, setToastMessage] = useState<string | null>(null);

  const mediaRecorderRef = useRef<MediaRecorder | null>(null);
  const audioChunksRef = useRef<Blob[]>([]);

  const showToast = (msg: string) => setToastMessage(msg);

  const handleFileChange = useCallback((files: File[] | null) => {
    dispatch({ type: 'SET_UPLOADED_FILES', files: files || [] });
  }, []);

  const processFilesForNotes = async (sources: (File | Blob)[]) => {
    const message = sources.some(s => s instanceof Blob) ? "Synthesizing Voice Data..." : "Extracting Intelligence...";
    dispatch({ type: 'START_PROCESSING', message });

    const filesForProcessing = sources.map((source) => {
      if (source instanceof File) return source;
      const mimeType = source.type || 'audio/webm';
      const recordingName = `live_recording.${mimeType.split('/')[1] || 'webm'}`;
      return new File([source], recordingName, { type: mimeType });
    });

    try {
      const notes = await generateNotesFromFiles(filesForProcessing);
      dispatch({ type: 'PROCESSING_SUCCESS', notes, processedAudios: filesForProcessing });
    } catch (err) {
      const errorMessage = err instanceof Error ? err.message : "An unknown error occurred.";
      dispatch({ type: 'PROCESSING_ERROR', error: errorMessage });
    }
  };

  const handleGenerateNotes = () => {
    if (state.uploadedFiles.length > 0) {
      processFilesForNotes(state.uploadedFiles);
    } else if (state.recordedAudioBlob) {
      processFilesForNotes([state.recordedAudioBlob]);
    }
  };

  const handleStartRecording = async () => {
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      dispatch({ type: 'START_RECORDING' });
      mediaRecorderRef.current = new MediaRecorder(stream);
      audioChunksRef.current = [];
      mediaRecorderRef.current.ondataavailable = (event) => audioChunksRef.current.push(event.data);
      mediaRecorderRef.current.onstop = () => {
        const mimeType = mediaRecorderRef.current?.mimeType || 'audio/webm';
        const audioBlob = new Blob(audioChunksRef.current, { type: mimeType });
        dispatch({ type: 'STOP_RECORDING', blob: audioBlob });
        stream.getTracks().forEach(track => track.stop());
      };
      mediaRecorderRef.current.start();
    } catch (err) {
      const error = err instanceof Error ? `Could not start recording: ${err.message}` : "Failed to access microphone.";
      dispatch({ type: 'PROCESSING_ERROR', error });
    }
  };

  const handleStopRecording = () => {
    if (mediaRecorderRef.current && state.isRecording) {
      mediaRecorderRef.current.stop();
    }
  };

  const handleSpecificQuerySubmit = async (queryText: string) => {
    if (!state.processedInitialAudios || !queryText.trim()) return;
    dispatch({ type: 'START_QUERY', queryText });
    try {
      const result = await generateSpecificInfoFromFiles(state.processedInitialAudios, queryText);
      dispatch({ type: 'QUERY_SUCCESS', queryText, answer: result });
    } catch (err) {
      const error = err instanceof Error ? err.message : "An unknown error occurred.";
      dispatch({ type: 'QUERY_ERROR', queryText, error });
    }
  };

  const handleReset = () => {
    if (mediaRecorderRef.current?.state === "recording") {
      mediaRecorderRef.current.stop();
    }
    dispatch({ type: 'RESET' });
  };

  const canGenerate = state.uploadedFiles.length > 0 || state.recordedAudioBlob;

  const handleDragEnter = (e: DragEvent<HTMLDivElement>) => {
    e.preventDefault();
    e.stopPropagation();
    if (disabledForDrop()) return;
    setIsDragging(true);
  };

  const handleDragOver = (e: DragEvent<HTMLDivElement>) => {
    e.preventDefault();
    e.stopPropagation();
  };

  const handleDragLeave = (e: DragEvent<HTMLDivElement>) => {
    e.preventDefault();
    e.stopPropagation();
    setIsDragging(false);
  };

  const handleDrop = (e: DragEvent<HTMLDivElement>) => {
    e.preventDefault();
    e.stopPropagation();
    setIsDragging(false);
    if (disabledForDrop()) return;

    const files = e.dataTransfer.files;
    if (files && files.length > 0) {
      const allowedExtensions = ['.docx', '.doc', '.pdf', '.txt', '.md'];
      const allowedFiles = Array.from(files).filter((file: File) => {
        const isAudio = file.type.startsWith('audio/');
        const isText = file.type.startsWith('text/');
        const isDoc = file.type === 'application/pdf' || 
                      file.type.includes('wordprocessingml') || 
                      file.type === 'application/msword' ||
                      allowedExtensions.some(ext => file.name.toLowerCase().endsWith(ext));
        return isAudio || isText || isDoc;
      });

      if (allowedFiles.length > 0) {
        handleFileChange(allowedFiles);
      } else {
        alert("No valid audio, document, or text files dropped.");
      }
    }
  };

  const disabledForDrop = () => state.isRecording || !!state.recordedAudioBlob;

  const renderContent = () => {
    switch (state.status) {
      case 'processing':
        return <ProcessingAnimation message={state.processingMessage} />;
      case 'success':
        return (
          <div className="w-full h-full flex flex-col">
            {/* Fixed Height Note Display */}
            <div className="flex-grow min-h-0 relative">
                <div className="absolute inset-0 overflow-y-auto pr-2 scrollbar-hide">
                    <NoteDisplay
                        notes={state.generatedNotes!}
                        editedNotes={state.editedNotes!}
                        onNotesChange={(newNotes) => dispatch({ type: 'UPDATE_EDITED_NOTES', notes: newNotes })}
                        onToast={showToast}
                    />
                </div>
            </div>

            {/* Bottom Control Bar */}
            <div className="flex-shrink-0 pt-4 mt-4 border-t border-white/20 grid grid-cols-1 lg:grid-cols-[1fr_auto_1fr] gap-4 items-end">
               {/* Left: New Session */}
               <div className="order-3 lg:order-1 flex justify-center lg:justify-start">
                   <button onClick={handleReset} className="text-text-muted hover:text-text-main flex items-center text-sm px-4 py-2 rounded-lg hover:bg-white/20 transition-colors">
                      <ArrowPathIcon className="w-4 h-4 mr-2" />
                      New Session
                  </button>
               </div>

               {/* Center: Chat */}
               <div className="order-1 lg:order-2 w-full">
                  <ChatQuery
                    onQuerySubmit={handleSpecificQuerySubmit}
                    queries={state.queries}
                    disabled={!state.processedInitialAudios}
                  />
               </div>

               {/* Right Spacer for balance */}
               <div className="hidden lg:block order-3"></div>
            </div>
          </div>
        );
      case 'idle':
      case 'error':
      default:
        return (
           <div className="w-full h-full flex flex-col items-center justify-center text-center relative z-10"
                onDragEnter={handleDragEnter}
                onDragOver={handleDragOver}
                onDragLeave={handleDragLeave}
                onDrop={handleDrop}
           >
                {isDragging && (
                  <div className="absolute inset-0 bg-accent-primary/5 backdrop-blur-sm border-2 border-dashed border-accent-primary rounded-3xl flex flex-col items-center justify-center z-20 pointer-events-none animate-pulse">
                      <UploadIcon className="w-16 h-16 text-accent-primary mb-4" />
                      <p className="text-xl font-bold text-accent-primary tracking-wide">Drop intelligence files here</p>
                  </div>
                )}

                <div style={{'--stagger': 1} as React.CSSProperties} className="animate-fade-in-stagger">
                    <h1 className="text-5xl font-bold text-text-main tracking-tight mb-2">MTS Aether</h1>
                    <p className="text-text-muted text-lg font-light">Advanced Moving Logistics Synthesis</p>
                </div>

                <div style={{'--stagger': 2} as React.CSSProperties} className="animate-fade-in-stagger my-10 flex items-center justify-center space-x-8">
                    <div className="flex flex-col items-center space-y-3 group">
                         <FileUpload onFileChange={handleFileChange} disabled={state.isRecording || !!state.recordedAudioBlob} />
                         <span className="text-xs font-medium text-text-muted group-hover:text-accent-primary transition-colors">UPLOAD FILES</span>
                    </div>
                    <div className="h-16 w-px bg-gray-300/50"></div>
                    <div className="flex flex-col items-center space-y-3 group">
                        <CallRecorder isRecording={state.isRecording} onStartRecording={handleStartRecording} onStopRecording={handleStopRecording} disabled={state.uploadedFiles.length > 0} />
                         <span className="text-xs font-medium text-text-muted group-hover:text-red-500 transition-colors">RECORD CALL</span>
                    </div>
                </div>

                <div className="h-12 flex items-center justify-center">
                    {state.uploadedFiles.length > 0 && (
                        <div style={{'--stagger': 3} as React.CSSProperties} className="animate-fade-in-stagger px-4 py-2 bg-white/50 rounded-full border border-white/60 shadow-sm">
                            <p className="text-sm text-text-main font-medium">{state.uploadedFiles.length} file(s) ready for analysis.</p>
                        </div>
                    )}
                    {state.recordedAudioBlob && !state.isRecording && (
                         <div style={{'--stagger': 3} as React.CSSProperties} className="animate-fade-in-stagger px-4 py-2 bg-red-50/50 rounded-full border border-red-100 shadow-sm">
                            <p className="text-sm text-red-600 font-medium flex items-center"><span className="w-2 h-2 rounded-full bg-red-500 mr-2 animate-pulse"></span>Audio captured.</p>
                        </div>
                    )}
                </div>

                {canGenerate && (
                <div style={{'--stagger': 4} as React.CSSProperties} className="animate-fade-in-stagger mt-8 w-full text-center">
                    <button
                    onClick={handleGenerateNotes}
                    className="px-10 py-4 bg-accent-primary hover:bg-accent-primary/90 text-white font-bold rounded-2xl shadow-[0_4px_20px_rgba(0,191,255,0.3)] hover:shadow-[0_6px_25px_rgba(0,191,255,0.5)] transition-all duration-300 ease-in-out transform hover:-translate-y-1 flex items-center justify-center mx-auto text-lg"
                    >
                    <SparklesIcon className="w-6 h-6 mr-2 animate-pulse" />
                    Initialize Synthesis
                    </button>
                </div>
                )}
            </div>
        );
    }
  };

  return (
    <div className="min-h-screen w-screen flex flex-col items-center justify-center p-4 md:p-8 selection:bg-accent-primary/30 selection:text-text-main overflow-hidden">
      {toastMessage && <Toast message={toastMessage} onClose={() => setToastMessage(null)} />}
      {state.status === 'error' && <ErrorMessage message={state.error!} onClear={() => dispatch({ type: 'CLEAR_ERROR' })} />}

      <main className={`glass-surface holographic-border rounded-3xl flex flex-col items-center justify-center transition-all duration-700 ease-[cubic-bezier(0.23,1,0.32,1)] relative overflow-hidden
        ${state.status === 'success' ? 'w-full max-w-6xl h-[92vh] p-6 md:p-8' : 'w-full max-w-2xl h-auto min-h-[600px] p-10'}
        ${state.isRecording ? '!border-red-400 shadow-[0_0_50px_rgba(248,113,113,0.3)]' : ''}
        `}
      >
        {/* Background Decorative Gradients */}
        <div className="absolute top-0 left-0 w-full h-full overflow-hidden -z-10 opacity-40 pointer-events-none">
             <div className="absolute top-[-10%] right-[-10%] w-[500px] h-[500px] bg-accent-primary/20 rounded-full blur-3xl animate-pulse-glow"></div>
             <div className="absolute bottom-[-10%] left-[-10%] w-[400px] h-[400px] bg-purple-300/20 rounded-full blur-3xl animate-pulse-glow" style={{ animationDelay: '1s' }}></div>
