`;

export const generateNotesFromFiles = async (
  files: File[]
): Promise<string> => {
  if (!files || files.length === 0) {
    throw new Error("No files provided for note generation.");
  }
  const localAi = getAiClient();
  try {
    const parts: Part[] = [];
    const fileNames: string[] = files.map(file => file.name);

    for (const file of files) {
      const fileName = file.name.toLowerCase();
      if (file.type.startsWith('audio/')) {
        const base64Audio = await fileToBase64(file);
        const audioMimeType = file.type || 'audio/webm';
        parts.push({ inlineData: { mimeType: audioMimeType, data: base64Audio } });
      } else if (file.type === 'application/pdf' || file.type.includes('wordprocessingml') || file.type === 'application/msword' || fileName.endsWith('.docx') || fileName.endsWith('.doc') || fileName.endsWith('.pdf')) {
        // Handle Word/PDF as binary inlineData
        const base64Data = await fileToBase64(file);
        // Ensure we provide a valid mimeType even if browser doesn't detect it
        let mimeType = file.type;
        if (!mimeType) {
          if (fileName.endsWith('.pdf')) mimeType = 'application/pdf';
          else if (fileName.endsWith('.docx')) mimeType = 'application/vnd.openxmlformats-officedocument.wordprocessingml.document';
          else if (fileName.endsWith('.doc')) mimeType = 'application/msword';
        }
        parts.push({ inlineData: { mimeType: mimeType || 'application/octet-stream', data: base64Data } });
      } else if (file.type.startsWith('text/') || fileName.endsWith('.md') || fileName.endsWith('.txt')) {
        const textContent = await readTextFile(file);
        parts.push({ text: `\n\n--- START CONTENT FROM FILE: ${file.name} ---\n${textContent}\n--- END CONTENT ---\n\n` });
      } else {
        // Fallback for unknown types - try as text if it's small, otherwise binary
        if (file.size < 1024 * 1024) { // 1MB
           const textContent = await readTextFile(file);
           parts.push({ text: `\n\n--- START CONTENT FROM UNKNOWN FILE: ${file.name} ---\n${textContent}\n--- END CONTENT ---\n\n` });
        }
      }
    }

    const userPrompt = `Analyze these files (${fileNames.join(', ')}) and generate the Operational Briefing. Ensure you read any meeting notes from the provided documents.`;

    parts.push({ text: userPrompt });

    const response: GenerateContentResponse = await localAi.models.generateContent({
      model: 'gemini-2.5-flash',
      contents: { parts },
      config: {
        systemInstruction: BASE_INSTRUCTION,
      },
    });

